-- Isolated SQLite fixture matching prisma/schema.prisma; never applied to the development database.
PRAGMA foreign_keys = ON;
CREATE TABLE SiteSetting (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);
CREATE TABLE Session (idHash TEXT PRIMARY KEY NOT NULL, data TEXT NOT NULL, expiresAt DATETIME NOT NULL);
CREATE INDEX Session_expiresAt_idx ON Session(expiresAt);
CREATE TABLE User (id TEXT PRIMARY KEY NOT NULL, role TEXT NOT NULL, displayName TEXT NOT NULL, email TEXT NOT NULL UNIQUE, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Category (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL, priceCents INTEGER NOT NULL, imageUrl TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL);
CREATE TABLE SupplierContact (id TEXT PRIMARY KEY NOT NULL, categoryId TEXT NOT NULL REFERENCES Category(id) ON DELETE CASCADE ON UPDATE CASCADE, supplierName TEXT NOT NULL, email TEXT NOT NULL, telephone TEXT, whatsapp TEXT, website TEXT, notes TEXT, supplierId TEXT REFERENCES SupplierProfile(userId) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Order" (id TEXT PRIMARY KEY NOT NULL, orderNumber TEXT NOT NULL UNIQUE, userId TEXT REFERENCES User(id) ON DELETE SET NULL ON UPDATE CASCADE, customerEmail TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', totalCents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'EUR', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE OrderItem (id TEXT PRIMARY KEY NOT NULL, orderId TEXT NOT NULL REFERENCES "Order"(id) ON DELETE CASCADE ON UPDATE CASCADE, categoryId TEXT NOT NULL REFERENCES Category(id) ON DELETE RESTRICT ON UPDATE CASCADE, categoryName TEXT NOT NULL, priceCents INTEGER NOT NULL, quantity INTEGER NOT NULL DEFAULT 1);
CREATE TABLE Payment (id TEXT PRIMARY KEY NOT NULL, orderId TEXT NOT NULL UNIQUE REFERENCES "Order"(id) ON DELETE CASCADE ON UPDATE CASCADE, status TEXT NOT NULL DEFAULT 'PENDING', provider TEXT NOT NULL DEFAULT 'DUMMY', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL, confirmedAt DATETIME, paymentIntentId TEXT, refundedCents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE EmailDelivery (id TEXT PRIMARY KEY NOT NULL, orderId TEXT NOT NULL UNIQUE REFERENCES "Order"(id) ON DELETE CASCADE ON UPDATE CASCADE, status TEXT NOT NULL DEFAULT 'NOT_SENT', recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lastError TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL);
CREATE INDEX SupplierContact_categoryId_idx ON SupplierContact(categoryId);
CREATE INDEX Order_userId_createdAt_idx ON "Order"(userId, createdAt);
CREATE INDEX OrderItem_orderId_idx ON OrderItem(orderId);
CREATE INDEX OrderItem_categoryId_idx ON OrderItem(categoryId);
CREATE TABLE Account (userId TEXT NOT NULL PRIMARY KEY REFERENCES User(id) ON DELETE CASCADE ON UPDATE CASCADE, passwordHash TEXT NOT NULL, emailVerifiedAt DATETIME, sessionVersion INTEGER NOT NULL DEFAULT 0);
CREATE TABLE AuthToken (idHash TEXT NOT NULL PRIMARY KEY, userId TEXT NOT NULL REFERENCES Account(userId) ON DELETE CASCADE ON UPDATE CASCADE, purpose TEXT NOT NULL, expiresAt DATETIME NOT NULL, usedAt DATETIME);
CREATE UNIQUE INDEX AuthToken_userId_purpose_key ON AuthToken(userId, purpose);
CREATE INDEX AuthToken_expiresAt_idx ON AuthToken(expiresAt);
CREATE TABLE AuthEmail (id TEXT NOT NULL PRIMARY KEY, userId TEXT NOT NULL REFERENCES Account(userId) ON DELETE CASCADE ON UPDATE CASCADE, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX AuthEmail_userId_createdAt_idx ON AuthEmail(userId, createdAt);
CREATE TABLE AuthRateLimit (keyHash TEXT NOT NULL PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, expiresAt DATETIME NOT NULL);
CREATE INDEX AuthRateLimit_expiresAt_idx ON AuthRateLimit(expiresAt);
CREATE TABLE SupplierProfile (userId TEXT NOT NULL PRIMARY KEY REFERENCES User(id) ON DELETE CASCADE ON UPDATE CASCADE, active BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX SupplierContact_supplierId_idx ON SupplierContact(supplierId);

CREATE TABLE IF NOT EXISTS PaymentAttempt (id TEXT NOT NULL PRIMARY KEY, paymentId TEXT NOT NULL REFERENCES Payment(id) ON DELETE CASCADE ON UPDATE CASCADE, status TEXT NOT NULL DEFAULT 'CREATING', sessionId TEXT, intentId TEXT, expiresAt DATETIME NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS PaymentAttempt_sessionId_key ON PaymentAttempt(sessionId);
CREATE UNIQUE INDEX IF NOT EXISTS PaymentAttempt_intentId_key ON PaymentAttempt(intentId);
CREATE INDEX IF NOT EXISTS PaymentAttempt_paymentId_createdAt_idx ON PaymentAttempt(paymentId, createdAt);
CREATE TABLE IF NOT EXISTS PaymentEvent (id TEXT NOT NULL PRIMARY KEY, eventId TEXT, paymentId TEXT NOT NULL REFERENCES Payment(id) ON DELETE CASCADE ON UPDATE CASCADE, kind TEXT NOT NULL, status TEXT NOT NULL, amountCents INTEGER NOT NULL, currency TEXT NOT NULL, actorId TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS PaymentEvent_eventId_key ON PaymentEvent(eventId);
CREATE INDEX IF NOT EXISTS PaymentEvent_paymentId_createdAt_idx ON PaymentEvent(paymentId, createdAt);
CREATE TABLE IF NOT EXISTS PaymentRefund (id TEXT NOT NULL PRIMARY KEY, paymentId TEXT NOT NULL REFERENCES Payment(id) ON DELETE CASCADE ON UPDATE CASCADE, providerRefundId TEXT, amountCents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'REQUESTED', actorId TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS PaymentRefund_providerRefundId_key ON PaymentRefund(providerRefundId);
CREATE INDEX IF NOT EXISTS PaymentRefund_paymentId_createdAt_idx ON PaymentRefund(paymentId, createdAt);
CREATE UNIQUE INDEX IF NOT EXISTS Payment_paymentIntentId_key ON Payment(paymentIntentId);
